#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n\"\"\"\nأداة التثبيت والإعداد\nتثبيت جميع المتطلبات وإعداد النظام للعمل\n\"\"\"\n\nimport os\nimport sys\nimport subprocess\nfrom pathlib import Path\n\nclass SetupHelper:\n    \"\"\"\n    مساعد التثبيت والإعداد\n    \"\"\"\n    def __init__(self):\n        self.project_root = Path(__file__).parent\n        self.backtesting_dir = self.project_root / \"backtesting\"\n    \n    def check_python_version(self):\n        \"\"\"\n        التحقق من إصدار Python\n        \"\"\"\n        print(\"\\n🔍 فحص إصدار Python...\")\n        version = sys.version_info\n        \n        if version.major < 3 or (version.major == 3 and version.minor < 7):\n            print(f\"❌ Python {version.major}.{version.minor} غير مدعوم\")\n            print(f\"⚠️ تحتاج Python 3.7 أو أحدث\")\n            return False\n        \n        print(f\"✅ Python {version.major}.{version.minor}.{version.micro} مناسب\")\n        return True\n    \n    def check_pip(self):\n        \"\"\"\n        التحقق من pip\n        \"\"\"\n        print(\"\\n🔍 فحص pip...\")\n        try:\n            result = subprocess.run(\n                [sys.executable, \"-m\", \"pip\", \"--version\"],\n                capture_output=True,\n                text=True\n            )\n            if result.returncode == 0:\n                print(f\"✅ {result.stdout.strip()}\")\n                return True\n        except:\n            pass\n        \n        print(\"❌ pip غير مثبت\")\n        return False\n    \n    def install_requirements(self):\n        \"\"\"\n        تثبيت المكتبات المطلوبة\n        \"\"\"\n        print(\"\\n📦 تثبيت المكتبات...\")\n        \n        # المكتبات الأساسية\n        basic_packages = [\"pandas\", \"numpy\"]\n        \n        # المكتبات الإضافية (اختيارية)\n        optional_packages = [\"yfinance\", \"requests\"]\n        \n        print(\"\\n📦 تثبيت المكتبات الأساسية:\")\n        for package in basic_packages:\n            print(f\"   • تثبيت {package}...\", end=\"\")\n            try:\n                subprocess.run(\n                    [sys.executable, \"-m\", \"pip\", \"install\", package, \"-q\"],\n                    timeout=60\n                )\n                print(\" ✅\")\n            except:\n                print(f\" ❌\")\n                return False\n        \n        print(\"\\n📦 تثبيت المكتبات الإضافية (اختيارية):\")\n        for package in optional_packages:\n            print(f\"   • تثبيت {package}...\", end=\"\")\n            try:\n                subprocess.run(\n                    [sys.executable, \"-m\", \"pip\", \"install\", package, \"-q\"],\n                    timeout=60\n                )\n                print(\" ✅\")\n            except:\n                print(f\" ⚠️ اختياري فقط\")\n        \n        return True\n    \n    def create_directories(self):\n        \"\"\"\n        إنشاء المجلدات المطلوبة\n        \"\"\"\n        print(\"\\n📁 إنشاء المجلدات...\")\n        \n        directories = [\n            self.backtesting_dir / \"forex_data\",\n            self.backtesting_dir / \"results\"\n        ]\n        \n        for directory in directories:\n            try:\n                directory.mkdir(parents=True, exist_ok=True)\n                print(f\"   ✅ {directory.name}/\")\n            except Exception as e:\n                print(f\"   ❌ خطأ: {e}\")\n                return False\n        \n        return True\n    \n    def verify_files(self):\n        \"\"\"\n        التحقق من وجود الملفات المهمة\n        \"\"\"\n        print(\"\\n🔍 التحقق من الملفات...\")\n        \n        required_files = [\n            \"standalone_backtester.py\",\n            \"advanced_optimizer.py\",\n            \"requirements.txt\",\n            \"QUICK_START.md\"\n        ]\n        \n        all_exist = True\n        for file in required_files:\n            file_path = self.backtesting_dir / file\n            if file_path.exists():\n                print(f\"   ✅ {file}\")\n            else:\n                print(f\"   ❌ {file} - غير موجود\")\n                all_exist = False\n        \n        return all_exist\n    \n    def run_setup(self):\n        \"\"\"\n        تشغيل عملية الإعداد الكاملة\n        \"\"\"\n        print(\"\\n\" + \"=\"*80)\n        print(\"🚀 إعداد نظام الاختبار الخلفي للمتداول الآلي\")\n        print(\"=\"*80)\n        \n        # فحص Python\n        if not self.check_python_version():\n            return False\n        \n        # فحص pip\n        if not self.check_pip():\n            print(\"❌ لا يمكن المتابعة بدون pip\")\n            return False\n        \n        # إنشاء المجلدات\n        if not self.create_directories():\n            print(\"❌ فشل إنشاء المجلدات\")\n            return False\n        \n        # التحقق من الملفات\n        if not self.verify_files():\n            print(\"⚠️ بعض الملفات غير موجودة\")\n        \n        # تثبيت المكتبات\n        print(\"\\n\" + \"=\"*80)\n        print(\"هل تريد تثبيت المكتبات الآن? (y/n)\")\n        choice = input(\"الاختيار: \").lower().strip()\n        \n        if choice == 'y':\n            if not self.install_requirements():\n                print(\"❌ فشل التثبيت\")\n                return False\n        \n        print(\"\\n\" + \"=\"*80)\n        print(\"✅ اكتمل الإعداد بنجاح!\")\n        print(\"=\"*80)\n        \n        self.print_next_steps()\n        return True\n    \n    def print_next_steps(self):\n        \"\"\"\n        طباعة الخطوات التالية\n        \"\"\"\n        print(\"\\n📋 الخطوات التالية:\\n\")\n        print(\"1️⃣ ادخل للمجلد:\")\n        print(\"   cd backtesting\\n\")\n        print(\"2️⃣ اقرأ الدليل السريع:\")\n        print(\"   - QUICK_START.md\\n\")\n        print(\"3️⃣ شغل الاختبار:\")\n        print(\"   python3 standalone_backtester.py\\n\")\n        print(\"4️⃣ شغل التحسين (اختياري):\")\n        print(\"   python3 advanced_optimizer.py\\n\")\n        print(\"5️⃣ اقرأ النتائج:\")\n        print(\"   - backtesting_results.json\\n\")\n\n\nif __name__ == \"__main__\":\n    setup = SetupHelper()\n    success = setup.run_setup()\n    \n    if not success:\n        print(\"\\n❌ فشل الإعداد\")\n        sys.exit(1)\n    else:\n        print(\"\\n🎉 البرنامج جاهز للاستخدام!\\n\")\n        sys.exit(0)\n"